-- Explicit gem-mainline-coin-exchange-v1; operator edits are preserved on replay.
-- Compute next month from the Beijing first day before converting back to UTC.
SET @gem_beijing = CONVERT_TZ(UTC_TIMESTAMP(), '+00:00', '+08:00');
SET @gem_month = DATE_FORMAT(@gem_beijing, '%Y%m');
SET @gem_start_local = STR_TO_DATE(CONCAT(@gem_month,'01'), '%Y%m%d');
SET @gem_start = TIMESTAMPDIFF(SECOND,'1970-01-01 00:00:00',DATE_SUB(@gem_start_local, INTERVAL 8 HOUR))*1000;
SET @gem_end = TIMESTAMPDIFF(SECOND,'1970-01-01 00:00:00',DATE_SUB(DATE_ADD(@gem_start_local, INTERVAL 1 MONTH), INTERVAL 8 HOUR))*1000;
INSERT IGNORE INTO p4_commerce_rules(id,shop_type,kind,enabled,start_at,end_at,claim_end_at,rules,source)
VALUES(CONCAT('limitExchange_p4_gem_',@gem_month),0,'exchange',FALSE,@gem_start,@gem_end,@gem_end,'{"products":[{"id":"item_137","name":"五级宝石随机包","index":1,"rewards":"item_137,1","cost":"coin,2000000","priority":1001,"dailyLimit":1,"totalLimit":3,"stock":-1,"minLevel":55,"minVip":0,"discountBps":10000,"weight":1},{"id":"item_342","name":"7级宝石选择箱","index":2,"rewards":"item_342,1","cost":"coin,7000000","priority":1002,"dailyLimit":1,"totalLimit":3,"stock":-1,"minLevel":70,"minVip":0,"discountBps":10000,"weight":1},{"id":"item_343","name":"8级宝石选择箱","index":3,"rewards":"item_343,1","cost":"coin,8000000","priority":1003,"dailyLimit":1,"totalLimit":3,"stock":-1,"minLevel":75,"minVip":0,"discountBps":10000,"weight":1},{"id":"item_344","name":"9级宝石选择箱","index":4,"rewards":"item_344,1","cost":"coin,9000000","priority":1004,"dailyLimit":1,"totalLimit":3,"stock":-1,"minLevel":80,"minVip":0,"discountBps":10000,"weight":1},{"id":"item_345","name":"10级宝石选择箱","index":5,"rewards":"item_345,1","cost":"coin,10000000","priority":1005,"dailyLimit":1,"totalLimit":3,"stock":-1,"minLevel":85,"minVip":0,"discountBps":10000,"weight":1}]}','gem-mainline-coin-exchange-v1：原164表未留item137/342/343/344/345生产配置，原服投放、兑换价格/窗口/限额未知；具名本地每份1原宝石包，按原5/7/8/9/10级宝石制造金币200000/700000/800000/900000/1000000的十倍替代缺少的原料，分别200万/700万/800万/900万/1000万金币；玩家55/70/75/80/85级，每玩家每天1份、每月3份；独立北京时间月窗口，真实金币来源与原ItemUse六色概率/选项保留');

